from pathlib import Path
import shutil
root=Path(__file__).resolve().parents[1];out=root/'site';out.mkdir(exist_ok=True)
shutil.copy2(root/'v1/openapi.json',out/'openapi.json')
assets=root/'node_modules/swagger-ui-dist'
for name in ('swagger-ui.css','swagger-ui-bundle.js','LICENSE'):shutil.copy2(assets/name,out/name)
(out/'index.html').write_text("""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Zenora API · QuantsLab</title><link rel="stylesheet" href="swagger-ui.css"><style>body{margin:0;background:#f7f8fc;color:#32253f;font-family:system-ui,sans-serif}header{padding:28px max(24px,calc((100% - 1400px)/2));border-bottom:1px solid #ddd6e5}h1{margin:0 0 8px;font-size:28px}nav{display:flex;flex-wrap:wrap;gap:18px;margin-top:14px}a{color:#714586}p{max-width:72ch;line-height:1.6}.swagger-ui .topbar{display:none}</style></head><body><header><h1>Zenora API</h1><p>Generation, private libraries and community integration. Built by QuantsLab.</p><nav><a href="https://github.com/QuantsLab-Zenora/zenora-developers/blob/main/v1/README.md">Get started</a><a href="https://github.com/QuantsLab-Zenora/zenora-developers/blob/main/v1/authentication.md">Authentication</a><a href="https://github.com/QuantsLab-Zenora/zenora-developers/blob/main/v1/workflows.md">Workflows</a><a href="openapi.json">Download OpenAPI</a></nav><p>This reference is read-only. Use the supplied native and HTTP examples for authenticated requests.</p></header><main id="swagger"></main><script src="swagger-ui-bundle.js"></script><script>SwaggerUIBundle({url:'openapi.json',dom_id:'#swagger',deepLinking:true,persistAuthorization:false,supportedSubmitMethods:[],defaultModelsExpandDepth:-1});</script></body></html>""",encoding='utf-8')
print('Built public API reference in site/')
